import sys
from itertools import permutations

def permute_brute(nums):
    return sorted(permutations(nums))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    for p in permute_brute(nums):
        print(' '.join(map(str, p)))

import sys

def permute_opt(nums):
    res = []
    def backtrack(i):
        if i == len(nums):
            res.append(nums[:])
        for j in range(i, len(nums)):
            nums[i], nums[j] = nums[j], nums[i]
            backtrack(i + 1)
            nums[i], nums[j] = nums[j], nums[i]
    backtrack(0)
    return sorted(res)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    for p in permute_opt(nums):
        print(' '.join(map(str, p)))

import sys

def permute_best(nums):
    res = []
    used = [False] * len(nums)
    path = []
    def dfs():
        if len(path) == len(nums):
            res.append(path[:])
            return
        for i, x in enumerate(nums):
            if used[i]: continue
            used[i] = True
            path.append(x)
            dfs()
            path.pop()
            used[i] = False
    dfs()
    return sorted(res)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    for p in permute_best(nums):
        print(' '.join(map(str, p)))
